import math

def gcd(a, b):
    return math.gcd(a, b)

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(U):
    if len(U) != 3:
        return False
    a, b, c = U[0], U[1], U[2]

    # Condition 1: gcd(a, b, c) = 1
    if gcd3(a, b, c) != 1:
        return False

    # Condition 2: For any two distinct elements, the third divides their product.
    # U = {a, b, c}

    # Check c | ab
    if (a * b) % c != 0:
        return False

    # Check b | ac
    if (a * c) % b != 0:
        return False

    # Check a | bc
    if (b * c) % a != 0:
        return False

    return True

good_numbers = set()
MAX_PRODUCT = 1000

# We search for U = {a, b, c} with 1 <= a < b < c and abc < 1000

# Max a: a^3 < 1000 => a <= 9
for a in range(1, 10):
    # Max b: a * b^2 < 1000 => b < sqrt(1000/a)
    b_limit = int((1000 / a)**0.5)
    for b in range(a + 1, b_limit + 1):
        # Max c: a * b * c < 1000 => c < 1000 / (a*b)
        c_limit = 999 // (a * b)
        for c in range(b + 1, c_limit + 1):
            U = (a, b, c)
            m = a * b * c

            if is_good_set(list(U)):
                good_numbers.add(m)

# Sort and print the found good numbers
sorted_good_numbers = sorted(list(good_numbers))
print("Found Good Numbers m < 1000:")
print(sorted_good_numbers)
print(f"Total found: {len(sorted_good_numbers)}")
